/** The label of a port, '<name> - <code>'. */
export function portLabel(port: CapturedPort): string {
  return `${port.name} - ${port.code}`;
}

async chooseMeansOfTransport(label: string): Promise<void> {
  await this.meansOfTransport.selectOption({ label });
}

await expect(animalsPages.arrivalDetails.transportIdentificationItems).toHaveText([
